function [mhu] = trapeze_dke_jd(mhumin,mhumax,dmhu,dmhumax);%% Generates a grid with linear increase in the steps from the edge to the center%%   INPUTS:%%       - mhumin : lower bound for the grid%       - mhumax : upper bound for the grid%       - dmhu : egde grid step%       - dmhumax : maximum grid step%%   OUTPUTS:%%       - mhu : resulting grid%% J. Decker 11/29/02rfactor = dmhumax/dmhu;mhuw = (mhumax - mhumin)/2;if mhuw >= 2*dmhu & rfactor >= 2    for i=1:rfactor-1        mhun(i) = dmhu*((i+2)*(i+1)/2-1);    end    n = max(find(mhun <= mhuw));    j = n;    while j > 0        d = 2*(mhuw - mhun(j));        dmhuj = (j+1)*dmhu;        dmhujp = (j+2)*dmhu;        m = floor(d/dmhuj);        if m > 0 & (d/m) <= dmhujp            mhum = mhumin + [0 mhun(1:j-1)];            mhup = mhumax - [0 mhun(1:j-1)];            mhuc = linspace(mhumin + mhun(j),mhumax - mhun(j),m+1);            mhu = [mhum,mhup,mhuc];            break        end        j = j-1;    endelse    j=0;endif j == 0    d = 2*mhuw;    dmhuj = dmhu;    m = floor(d/dmhuj);    mhu = linspace(mhumin,mhumax,m+2);endmhu = sort(mhu);    